```{.r .cell-code}
library(cbbplotR)
library(rlang)

cross_conf_p4_2026 <- readr::read_csv("cross_conf_p4_2026.csv")


cc_p4 <- cross_conf_p4_2026 |> 
  dplyr::mutate(game_date = as.Date(game_date, format = "%m/%d/%y")) |> 
  dplyr::mutate(week = dplyr::if_else(game_date < "2026-09-03", 0, week)) |> 
  cbbplotR::gt_cbb_teams(away_team, away_team, include_name = FALSE) |> 
  cbbplotR::gt_cbb_teams(home_team, home_team, include_name = FALSE) |> 
  dplyr::mutate(matchup = paste0(away_team, " ", home_team)) |> 
  dplyr::select(week, matchup) |> 

  dplyr::group_by(week) |> 
  dplyr::mutate(game_id = paste0("g", dplyr::row_number())) |> 
  dplyr::ungroup() |> 
  tidyr::pivot_wider(
    names_from = game_id, 
    values_from = matchup
  ) |> 
  tidyr::complete(week = 0:13)


fball_header <- glue::glue(
  "<div style='display: flex; justify-content: space-between; align-items: center;'>
      <div>
       <img src='https://a.espncdn.com/combiner/i?img=/redesign/assets/img/icons/ESPN-icon-football-college.png'
       style='height: 40px; width: auto; vertical-align: middle;'>
     </div>
     <div style='flex-grow:1; margin-left: 30px; margin-right: 30px'>
       <span style='display: block; font-weight: bold; text-align: center; font-size: 24px;'>2026 Regular Season Games <br>Between <em>Power</em> Conference Teams</span>
       <span style='font-size: 12px; font-weight: normal; display: block; text-align: center;'>There are 29 games scheduled between teams of the ACC, Big Ten, Big 12, and SEC. <br>No cross-conference games are scheduled between September 20th and November 27th.</span>
     </div>
     <div>
       <img src='https://a.espncdn.com/combiner/i?img=/redesign/assets/img/icons/ESPN-icon-football-college.png'
       style='height: 40px; width: auto; vertical-align: middle;'>
     </div>
   </div>
  <br>"
)



cc_p4 |> 
  gt::gt() |> 
  gtUtils::gt_theme_savant() |>
  gt::fmt_markdown(columns = gt::everything()) |> 
  gt::sub_missing(missing_text = "") |> 
  gt::cols_align(align = "center", columns = gt::everything()) |> 
  gt::cols_width(
    week ~ gt::px(60),
    dplyr::starts_with("g") ~ gt::px(70)
  ) |> 
  gt::cols_label_with(
    columns = dplyr::starts_with("g"),
    fn = \(x) ""
  ) |> 
  gt::cols_label(
    week = "Week"
  ) |> 
  gt::tab_header(title = gt::html(fball_header)) |>
  gtUtils::gt_border_grid(color = "black",
                          weight = 1,
                          include_labels = FALSE) |> 
  gt::tab_source_note(gt::html(
    "
     data via collegefootballdata.com | cfbtxt.com<br>
     <hr>
     Four of these 29 games are at <b>neutral sites</b>: UNC-TCU in Ireland, Baylor-Auburn in Atlanta, Louisville-Ole Miss in Nashville, and Virginia-West Virginia in Charlotte.<br>
     This chart <b>excludes independents like Notre Dame.</b> The Irish are scheduled to play 10 games against power conference teams: ACC (6), Big Ten (3), Big 12 (1), and SEC (0).</br>
     <hr>
     Table by Chris at Bless your Chart"
  )) |>
  gt::tab_options(
    table.font.size            = gt::px(14),
    heading.align              = "left",
    column_labels.font.weight  = "bold"
  ) |>
  gt::tab_style(
    style = list(gt::cell_borders(
      sides  = c("left", "right", "top", "bottom"),
      color  = "black",
      weight = gt::px(2)
    )),
    locations = list(
      gt::cells_body(),
      gt::cells_column_labels()
    )
  ) |>
  gtExtras::gt_highlight_rows(
    rows = c(5:13),
    fill = "#FEF2F2",
    font_weight = "normal",
    bold_target_only = FALSE
  ) |> 
  gtExtras::gt_highlight_rows(
    rows = c(1),
    columns = 2,
    fill = "#fffee0",
    font_weight = "normal",
    bold_target_only = FALSE
  ) |> 
  gtExtras::gt_highlight_rows(
    rows = c(2),
    columns = c(3, 7),
    fill = "#fffee0",
    font_weight = "normal",
    bold_target_only = FALSE
  ) |> 
  gtExtras::gt_highlight_rows(
    rows = c(4),
    columns = c(4),
    fill = "#fffee0",
    font_weight = "normal",
    bold_target_only = FALSE
  ) |> 
  gt::tab_options(table.width = gt::px(675)) -> cc_tbl

gt_save_crop(
  cc_tbl,
  file = "cc_tbl.png",
  whitespace = 40,
  bg = "white"
) 

cc_tbl
